class Solution {
public:
    long long minimumWeight(int n, vector<vector<int>>& edges, int src1, int src2, int dest) {
        vector<vector<pair<int, int>>> adj(n), radj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            radj[e[1]].push_back({e[0], e[2]});
        }

        auto dijkstra = [&](int start, const vector<vector<pair<int, int>>>& graph) {
            vector<long long> dist(n, LLONG_MAX);
            dist[start] = 0;
            priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
            pq.push({0, start});
            while (!pq.empty()) {
                auto [d, u] = pq.top();
                pq.pop();
                if (d > dist[u]) continue;
                for (const auto& [v, w] : graph[u]) {
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                        pq.push({dist[v], v});
                    }
                }
            }
            return dist;
        };

        auto d1 = dijkstra(src1, adj);
        auto d2 = dijkstra(src2, adj);
        auto d3 = dijkstra(dest, radj);

        long long ans = LLONG_MAX;
        for (int i = 0; i < n; i++) {
            if (d1[i] != LLONG_MAX && d2[i] != LLONG_MAX && d3[i] != LLONG_MAX) {
                ans = min(ans, d1[i] + d2[i] + d3[i]);
            }
        }
        return ans == LLONG_MAX ? -1 : ans;
    }
};

class Solution {
    public long minimumWeight(int n, int[][] edges, int src1, int src2, int dest) {
        List<List<int[]>> adj = new ArrayList<>();
        List<List<int[]>> radj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
            radj.add(new ArrayList<>());
        }
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            radj.get(e[1]).add(new int[]{e[0], e[2]});
        }

        long[] d1 = dijkstra(n, src1, adj);
        long[] d2 = dijkstra(n, src2, adj);
        long[] d3 = dijkstra(n, dest, radj);

        long ans = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (d1[i] != Long.MAX_VALUE && d2[i] != Long.MAX_VALUE && d3[i] != Long.MAX_VALUE) {
                ans = Math.min(ans, d1[i] + d2[i] + d3[i]);
            }
        }
        return ans == Long.MAX_VALUE ? -1 : ans;
    }

    private long[] dijkstra(int n, int start, List<List<int[]>> graph) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.add(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d > dist[u]) continue;
            for (int[] edge : graph.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.add(new long[]{dist[v], v});
                }
            }
        }
        return dist;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number} src1
 * @param {number} src2
 * @param {number} dest
 * @return {number}
 */
var minimumWeight = function(n, edges, src1, src2, dest) {
    const adj = Array.from({ length: n }, () => []);
    const radj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        radj[v].push([u, w]);
    }

    function dijkstra(start, graph) {
        const dist = new Array(n).fill(Infinity);
        dist[start] = 0;
        const pq = [[0, start]];
        while (pq.length > 0) {
            pq.sort((a, b) => a[0] - b[0]);
            const [d, u] = pq.shift();
            if (d > dist[u]) continue;
            for (const [v, w] of graph[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push([dist[v], v]);
                }
            }
        }
        return dist;
    }

    const d1 = dijkstra(src1, adj);
    const d2 = dijkstra(src2, adj);
    const d3 = dijkstra(dest, radj);

    let ans = Infinity;
    for (let i = 0; i < n; i++) {
        if (d1[i] < Infinity && d2[i] < Infinity && d3[i] < Infinity) {
            ans = Math.min(ans, d1[i] + d2[i] + d3[i]);
        }
    }
    return ans === Infinity ? -1 : ans;
};
